<?php
declare(strict_types=1);
/** Operational extensions: suppliers, stock receiving, cancellation approvals and push tokens. */
require_once __DIR__ . '/../../../includes/db.php';
require_once __DIR__ . '/../../../includes/utils.php';
use App\Inventory;
use App\Order;

$pdo = get_db(); $auth = require_auth(); $method = $_SERVER['REQUEST_METHOD'];
function op_roles(array $user, array $roles): void { if (!in_array($user['role'], $roles, true)) json_response(['error' => 'Forbidden'], 403); }
function op_body(): array { try { return get_json_body(); } catch (JsonException $e) { json_response(['error' => 'Invalid JSON body'], 400); } }

if ($method === 'GET') {
    $resource = (string)($_GET['resource'] ?? '');
    if ($resource === 'suppliers') { op_roles($auth, ['admin','owner','manager','supervisor']); $rows=$pdo->query('SELECT * FROM suppliers WHERE ' . demo_data_scope_sql('suppliers', $auth) . ' ORDER BY name')->fetchAll(); json_response(['success'=>true,'data'=>['suppliers'=>$rows]]); }
    if ($resource === 'receipts') { op_roles($auth, ['admin','owner','manager','supervisor']); $rows=$pdo->query('SELECT r.*,s.name AS supplier_name,u.name AS received_by_name FROM supply_receipts r JOIN suppliers s ON s.id=r.supplier_id JOIN users u ON u.id=r.received_by_user_id WHERE ' . demo_data_scope_sql('r', $auth) . ' AND ' . demo_data_scope_sql('s', $auth) . ' AND ' . demo_data_scope_sql('u', $auth) . ' ORDER BY r.received_at DESC LIMIT 100')->fetchAll(); json_response(['success'=>true,'data'=>['receipts'=>$rows]]); }
    if ($resource === 'cancellations') { op_roles($auth, ['admin','owner','manager','supervisor']); $stmt=$pdo->query("SELECT c.*,o.table_id,u.name AS requester_name FROM order_cancellation_requests c JOIN orders o ON o.id=c.order_id JOIN users u ON u.id=c.requested_by_user_id WHERE c.status='pending' AND " . demo_data_scope_sql('c', $auth) . ' AND ' . demo_data_scope_sql('o', $auth) . ' AND ' . demo_data_scope_sql('u', $auth) . " ORDER BY c.created_at ASC"); json_response(['success'=>true,'data'=>['requests'=>$stmt->fetchAll()]]); }
    json_response(['error'=>'Unknown resource'],400);
}
if ($method !== 'POST') json_response(['error'=>'Method not allowed'],405);
$body=op_body(); $action=(string)($body['action']??''); $now=date('Y-m-d H:i:s');
if ($action === 'supplier.create') {
    op_roles($auth,['admin','owner','manager']); $name=trim((string)($body['name']??'')); if($name==='')json_response(['error'=>'Supplier name is required'],422);
    $stmt=$pdo->prepare('INSERT INTO suppliers (name,contact_name,phone_number,email,address,notes,restaurant_id,created_at,updated_at) VALUES (:name,:contact,:phone,:email,:address,:notes,:restaurant,:now,:now)');$stmt->execute([':name'=>$name,':contact'=>trim((string)($body['contact_name']??''))?:null,':phone'=>trim((string)($body['phone_number']??''))?:null,':email'=>trim((string)($body['email']??''))?:null,':address'=>trim((string)($body['address']??''))?:null,':notes'=>trim((string)($body['notes']??''))?:null,':restaurant'=>$auth['restaurant_id']??null,':now'=>$now]);json_response(['success'=>true,'data'=>['id'=>(int)$pdo->lastInsertId()]],201);
}
if ($action === 'supply.receive') {
    op_roles($auth,['admin','owner','manager']);$supplier=(int)($body['supplier_id']??0);$items=$body['items']??[];if($supplier<=0||!is_array($items)||!$items)json_response(['error'=>'Supplier and one or more received items are required'],422);
    $pdo->beginTransaction();try{$s=$pdo->prepare('SELECT id FROM suppliers WHERE id=:id AND ' . demo_data_scope_sql('suppliers',$auth));$s->execute([':id'=>$supplier]);if(!$s->fetch())throw new InvalidArgumentException('Supplier not found');$r=$pdo->prepare('INSERT INTO supply_receipts (supplier_id,reference_number,received_by_user_id,notes,restaurant_id,received_at,created_at) VALUES (:supplier,:reference,:user,:notes,:restaurant,:now,:now)');$r->execute([':supplier'=>$supplier,':reference'=>trim((string)($body['reference_number']??''))?:null,':user'=>$auth['id'],':notes'=>trim((string)($body['notes']??''))?:null,':restaurant'=>$auth['restaurant_id']??null,':now'=>$now]);$receipt=(int)$pdo->lastInsertId();$inventory=new Inventory($pdo);$line=$pdo->prepare('INSERT INTO supply_receipt_items (supply_receipt_id,inventory_item_id,quantity,unit_cost,restaurant_id) VALUES (:receipt,:inventory,:quantity,:cost,:restaurant)');foreach($items as $item){$menu=(int)($item['menu_item_id']??0);$qty=(float)($item['quantity']??0);if($menu<=0||$qty<=0)throw new InvalidArgumentException('Each received item needs a menu item and positive quantity');$result=$inventory->adjustStock($menu,$qty,'Supply receipt #'.$receipt,$auth['id'],'stock_in',$receipt);$line->execute([':receipt'=>$receipt,':inventory'=>$result['inventory_item_id'],':quantity'=>$qty,':cost'=>isset($item['unit_cost'])?(float)$item['unit_cost']:null,':restaurant'=>$auth['restaurant_id']??null]);}$pdo->commit();json_response(['success'=>true,'data'=>['receipt_id'=>$receipt]],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['error'=>$e->getMessage()],422);}
}
if ($action === 'cancel.request') {
    op_roles($auth,['waiter']);$order=(int)($body['order_id']??0);$reason=trim((string)($body['reason']??''));if($order<=0||$reason==='')json_response(['error'=>'Order and cancellation reason are required'],422);$check=$pdo->prepare('SELECT id FROM orders WHERE id=:id AND waiter_id=:waiter AND status != :completed AND ' . demo_data_scope_sql('orders',$auth));$check->execute([':id'=>$order,':waiter'=>$auth['id'],':completed'=>'completed']);if(!$check->fetch())json_response(['error'=>'Only your active orders can be cancelled'],403);try{$pdo->prepare("INSERT INTO order_cancellation_requests (order_id,requested_by_user_id,reason,restaurant_id,created_at) VALUES (:order,:user,:reason,:restaurant,:now)")->execute([':order'=>$order,':user'=>$auth['id'],':reason'=>$reason,':restaurant'=>$auth['restaurant_id']??null,':now'=>$now]);create_notification($pdo,'manager',null,'Cancellation approval needed',"Waiter requested cancellation for order #{$order}",'alert','order',$order);json_response(['success'=>true,'data'=>['message'=>'Cancellation request submitted']],201);}catch(Throwable $e){json_response(['error'=>'A cancellation request is already pending for this order'],409);}
}
if ($action === 'cancel.review') {
    op_roles($auth,['admin','owner','manager','supervisor']);$id=(int)($body['request_id']??0);$decision=(string)($body['decision']??'');if($id<=0||!in_array($decision,['approved','rejected'],true))json_response(['error'=>'Valid request and decision are required'],422);try{$q=$pdo->prepare("SELECT * FROM order_cancellation_requests WHERE id=:id AND status='pending' AND " . demo_data_scope_sql('order_cancellation_requests',$auth));$q->execute([':id'=>$id]);$request=$q->fetch();if(!$request)throw new InvalidArgumentException('Pending cancellation request not found');if($decision==='approved'){(new Order($pdo))->cancel((int)$request['order_id'],$auth['id']);}$updated=$pdo->prepare("UPDATE order_cancellation_requests SET status=:status,reviewed_by_user_id=:reviewer,review_notes=:notes,reviewed_at=:now WHERE id=:id AND status='pending' AND " . demo_data_scope_sql('order_cancellation_requests',$auth));$updated->execute([':status'=>$decision,':reviewer'=>$auth['id'],':notes'=>trim((string)($body['review_notes']??''))?:null,':now'=>$now,':id'=>$id]);if($updated->rowCount()!==1)throw new InvalidArgumentException('Cancellation request was already reviewed');create_notification($pdo,'waiter',(int)$request['requested_by_user_id'],'Cancellation request '.$decision,"Order #{$request['order_id']} cancellation was {$decision}",'status_change','order',(int)$request['order_id']);json_response(['success'=>true,'data'=>['status'=>$decision]]);}catch(Throwable $e){json_response(['error'=>$e->getMessage()],422);}
}
if ($action === 'push.subscribe') { if(!firebase_messaging_enabled())json_response(['success'=>true,'data'=>['message'=>'Push subscriptions are temporarily disabled']]);$token=trim((string)($body['token']??''));$platform=(string)($body['platform']??'');if($token===''||!in_array($platform,['web','android','ios'],true))json_response(['error'=>'A valid platform and push token are required'],422);$pdo->prepare('INSERT INTO push_subscriptions (user_id,platform,token,created_at,updated_at) VALUES (:user,:platform,:token,:now,:now) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),platform=VALUES(platform),updated_at=VALUES(updated_at)')->execute([':user'=>$auth['id'],':platform'=>$platform,':token'=>$token,':now'=>$now]);json_response(['success'=>true,'data'=>['message'=>'Push subscription saved']]); }
json_response(['error'=>'Unknown action'],400);
